const money=(v,c='BYN')=>{const n=Number(v);return v==null||!Number.isFinite(n)?'Цена уточняется':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n)+' '+c};
const budgetLabel=v=>Number(v)===999?'Без лимита':money(v);
